import java.util.concurrent.*;

public final class BoundedIngestionExecutor {
    private static final int QUEUE_CAPACITY = 2048;
    private static final int HIGH_WATERMARK = 1800;
    private static final int LOW_WATERMARK = 1024;

    private final BlockingQueue<Runnable> queue = new ArrayBlockingQueue<>(QUEUE_CAPACITY);
    private final ThreadPoolExecutor pool = new ThreadPoolExecutor(
        16, 16, 0L, TimeUnit.MILLISECONDS, queue,
        r -> new Thread(r, "es-writer"),
        new ThreadPoolExecutor.AbortPolicy()
    );

    public boolean shouldPauseConsumer() {
        return queue.size() >= HIGH_WATERMARK;
    }

    public boolean shouldResumeConsumer() {
        return queue.size() <= LOW_WATERMARK;
    }

    public void submitHttpEvent(Runnable writeTask) {
        pool.execute(writeTask); // Throws RejectedExecutionException at 2048 -> map to HTTP 429
    }
}

// SynchronousQueue forces immediate thread scaling up to 64 before rejecting
ExecutorService elastic = new ThreadPoolExecutor(
    16, 64, 60L, TimeUnit.SECONDS,
    new SynchronousQueue<>(),
    new ThreadPoolExecutor.AbortPolicy()
);

// Byte-bounded admission prevents variable-size payloads from blowing up heap
private final Semaphore byteBudget = new Semaphore(64 * 1024 * 1024);

public void submit(byte[] payload, Runnable task) {
    if (!byteBudget.tryAcquire(payload.length)) {
        throw new RejectedExecutionException("64MB queue byte budget exhausted");
    }
    pool.execute(() -> {
        try { task.run(); }
        finally { byteBudget.release(payload.length); }
    });
}

